{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/logo-cloud.json
    A heading and the names of customers or partners as Lucide glyphs with a name. Axes: layout (grid, row), columns (2, 3, 4), item (name, icon only, tile), density, tone.
    Props (p): id, title, logos, layout, cols, item, tone, density, landmarkLabel. -#}
{%- set v_id = ui_def(p['id'], none) -%}
{%- set v_title = ui_def(p['title'], none) -%}
{%- set v_logos = ui_def(p['logos'], none) -%}
{%- set v_layout = ui_def(p['layout'], 'grid') -%}
{%- set v_cols = ui_def(p['cols'], '4') -%}
{%- set v_item = ui_def(p['item'], 'name') -%}
{%- set v_tone = ui_def(p['tone'], 'default') -%}
{%- set v_density = ui_def(p['density'], 'default') -%}
{%- set v_landmarkLabel = ui_def(p['landmarkLabel'], none) -%}
{%- if ui_t(ui_eq(v_layout, 'row')) %}
  {{ ui_include('blocks/logo-ribbon.html.j2', {'p': {'id': v_id, 'title': v_title, 'logos': v_logos, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}}) }}
{%- else %}
  {%- set c_4 -%}
    {%- set c_3 -%}
      {%- for v_logo in ui_l(v_logos) %}
        {%- set c_2 -%}
          {{ ui_include('ui/lucide-icon/lucide-icon.html.j2', {'p': {'Name': ui_s(ui_get(v_logo, ['icon'])), 'Size': 24}}) }}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_logo, ['name'])) }}
          {%- endset -%}
          {{ ui_include('ui/text/text.html.j2', {'p': {'Size': 'sm', 'Weight': 'semibold', 'Class': ui_s(('sr-only' if ui_t(ui_eq(v_item, 'icon')) else ''))}, 'children': c_1}) }}
        {%- endset -%}
        {{ ui_include('ui/group/group.html.j2', {'p': {'Gap': '2', 'Align': 'center', 'Justify': 'center', 'Class': ui_s(ui_cnv(['text-muted-foreground', ('flex-col rounded p-4 inset-ring inset-ring-border' if ui_t(ui_eq(v_item, 'tile')) else '')])), 'Attrs': ui_attrs(['data-testid', 'item'])}, 'children': c_2}) }}
      {%- endfor %}
    {%- endset -%}
    {{ ui_include('ui/grid/grid.html.j2', {'p': {'Cols': ui_s(('2' if ui_t(ui_eq(v_cols, '2')) else ('2-3' if ui_t(ui_eq(v_cols, '3')) else ('2-4' if ui_t(ui_eq(v_cols, '4')) else '3-6')))), 'Class': 'gap-4', 'Attrs': ui_attrs(['data-testid', 'items'])}, 'children': c_3}) }}
  {%- endset -%}
  {{ ui_include('blocks/section-frame.html.j2', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'align': 'center', 'landmarkLabel': v_landmarkLabel}, 'children': c_4}) }}
{%- endif %}
